// Validate and flatten the TradingView alert into ONE flat event.
// The fee gate is NOT fetched here: BTCMatic keeps its own live mempool
// view, and the rule's fee_next_block leaf is evaluated by the engine
// with fresh data at decision time. The evaluation trace will show every
// leaf (signal, rsi, fee_next_block, …) with pass/fail.
const alert = $json.body ?? {};

const rsi = Number(alert.rsi);
const price = Number(alert.price);
if (!Number.isFinite(rsi) || !Number.isFinite(price)) {
  throw new Error('TradingView alert must carry numeric "rsi" and "price" fields — check the alert message JSON (see README)');
}

return [{
  json: {
    fields: {
      signal: String(alert.signal ?? 'tv_alert'),
      ticker: String(alert.ticker ?? 'UNKNOWN'),
      rsi,
      price
    },
    // Dedup on the TradingView alert itself so a retry (or a manually
    // re-run execution) can never land as a fresh event, even if you later
    // add fields that vary between attempts.
    idempotency: `tv:${alert.ticker ?? 'x'}:${alert.time ?? $execution.id}`.slice(0, 128)
  }
}];
